import sys

def main(argv=None):
    args = list(argv or sys.argv[1:])
    if len(args) != 1 or not args[0].isdigit():
        print('invalid', file=sys.stderr)
        return 0
    print(int(args[0]) * 2)
    return 0

if __name__ == '__main__':
    raise SystemExit(main())

